export type OrderStatus = 'PENDING' | 'PAID' | 'SHIPPED' | 'CANCELLED';

export interface DomainEvent {
  readonly eventName: string;
  readonly occurredAt: Date;
  readonly aggregateId: string;
}

export class Money {
  readonly amount: number;
  readonly currency: string;

  constructor(amount: number, currency: string) {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error('Money amount must be a non-negative finite number');
    }
    if (!currency || currency.trim().length === 0) {
      throw new Error('Currency must be a non-empty string');
    }
    this.amount = Math.round(amount * 100) / 100;
    this.currency = currency.toUpperCase();
    Object.freeze(this);
  }

  static of(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  add(other: Money): Money {
    if (this.currency !== other.currency) {
      throw new Error(`Currency mismatch: cannot add ${other.currency} to ${this.currency}`);
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  equals(other: Money): boolean {
    return this.amount === other.amount && this.currency === other.currency;
  }
}

export interface OrderItem {
  id: string;
  quantity: number;
  price: Money;
}

export class Order {
  readonly id: string;
  readonly customerId: string;
  private _status: OrderStatus;
  private _items: OrderItem[] = [];
  private _domainEvents: DomainEvent[] = [];

  constructor(id: string, customerId: string) {
    if (!id || id.trim().length === 0) throw new Error('Order id cannot be empty');
    if (!customerId || customerId.trim().length === 0) throw new Error('Customer id cannot be empty');

    this.id = id;
    this.customerId = customerId;
    this._status = 'PENDING';
    this.recordEvent('OrderCreated', { orderId: this.id, customerId: this.customerId });
  }

  get status(): OrderStatus {
    return this._status;
  }

  get items(): ReadonlyArray<OrderItem> {
    return Object.freeze([...this._items]);
  }

  addItem(productId: string, quantity: number, price: Money): void {
    if (this._status !== 'PENDING') {
      throw new Error(`Cannot add item to order in ${this._status} status`);
    }
    if (!productId || productId.trim().length === 0) {
      throw new Error('Product id cannot be empty');
    }
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new Error('Item quantity must be a positive integer');
    }
    if (this._items.length > 0 && this._items[0]?.price.currency !== price.currency) {
      throw new Error(`Item currency ${price.currency} must match order currency ${this._items[0]?.price.currency}`);
    }

    const existingItem = this._items.find((item) => item.id === productId);
    if (existingItem) {
      existingItem.quantity += quantity;
    } else {
      this._items.push({ id: productId, quantity, price });
    }

    this.recordEvent('OrderItemAdded', { orderId: this.id, productId, quantity, price });
  }

  pay(): void {
    if (this._status !== 'PENDING') {
      throw new Error(`Order cannot be paid from current status: ${this._status}`);
    }
    if (this._items.length === 0) {
      throw new Error('Cannot pay for an empty order');
    }
    this._status = 'PAID';
    this.recordEvent('OrderPaid', { orderId: this.id, total: this.getTotal() });
  }

  ship(): void {
    if (this._status !== 'PAID') {
      throw new Error(`Order must be PAID before shipping. Current status: ${this._status}`);
    }
    this._status = 'SHIPPED';
    this.recordEvent('OrderShipped', { orderId: this.id });
  }

  cancel(): void {
    if (this._status === 'SHIPPED') {
      throw new Error('Cannot cancel an already shipped order');
    }
    if (this._status === 'CANCELLED') {
      throw new Error('Order is already cancelled');
    }
    this._status = 'CANCELLED';
    this.recordEvent('OrderCancelled', { orderId: this.id });
  }

  getTotal(): Money {
    if (this._items.length === 0) {
      return Money.of(0, 'USD');
    }
    const currency = this._items[0]!.price.currency;
    return this._items.reduce(
      (total, item) => total.add(Money.of(item.price.amount * item.quantity, currency)),
      Money.of(0, currency)
    );
  }

  getDomainEvents(): DomainEvent[] {
    return [...this._domainEvents];
  }

  private recordEvent(eventName: string, payload: Record<string, unknown>): void {
    this._domainEvents.push({
      eventName,
      occurredAt: new Date(),
      aggregateId: this.id,
      ...payload,
    });
  }
}

export interface IOrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

