export type CircuitState = 'CLOSED' | 'OPEN' | 'HALF_OPEN';

export interface CircuitBreakerOptions {
  failureThreshold?: number;
  resetTimeoutMs?: number;
}

export class CircuitBreaker {
  private currentState: CircuitState = 'CLOSED';
  private failureCount: number = 0;
  private nextAttempt: number = 0;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;

  constructor(options?: CircuitBreakerOptions) {
    this.failureThreshold = options?.failureThreshold ?? 5;
    this.resetTimeoutMs = options?.resetTimeoutMs ?? 10000;
  }

  get state(): CircuitState {
    return this.getState();
  }

  getState(): CircuitState {
    if (this.currentState === 'OPEN' && Date.now() >= this.nextAttempt) {
      this.currentState = 'HALF_OPEN';
    }
    return this.currentState;
  }

  recordSuccess(): void {
    this.failureCount = 0;
    this.currentState = 'CLOSED';
  }

  recordFailure(): void {
    this.failureCount++;
    if (this.currentState === 'HALF_OPEN' || this.failureCount >= this.failureThreshold) {
      this.currentState = 'OPEN';
      this.nextAttempt = Date.now() + this.resetTimeoutMs;
    }
  }

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this.getState() === 'OPEN') {
      throw new Error('Circuit breaker is OPEN');
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }
}

export class ApiError extends Error {
  readonly statusCode: number;

  constructor(message: string, statusCode: number) {
    super(message);
    this.name = 'ApiError';
    this.statusCode = statusCode;
    Object.setPrototypeOf(this, ApiError.prototype);
  }
}

export interface RequestOptions {
  timeoutMs?: number;
  headers?: Record<string, string>;
}

export class ResilientHttpClient {
  private readonly circuitBreaker: CircuitBreaker;

  constructor(circuitBreaker?: CircuitBreaker) {
    this.circuitBreaker = circuitBreaker ?? new CircuitBreaker();
  }

  async get<T>(url: string, options?: RequestOptions): Promise<T> {
    return this.circuitBreaker.execute(async () => {
      const controller = new AbortController();
      const timeoutId = options?.timeoutMs
        ? setTimeout(() => controller.abort(), options.timeoutMs)
        : undefined;

      try {
        const response = await fetch(url, {
          method: 'GET',
          headers: options?.headers,
          signal: controller.signal,
        });

        if (!response.ok) {
          throw new ApiError(
            `HTTP error ${response.status}: ${response.statusText}`,
            response.status
          );
        }

        return (await response.json()) as T;
      } catch (error: unknown) {
        if (error instanceof Error && error.name === 'AbortError') {
          throw new ApiError('Request timeout', 408);
        }
        throw error;
      } finally {
        if (timeoutId !== undefined) {
          clearTimeout(timeoutId);
        }
      }
    });

import crypto from "crypto";

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

interface UserRecord {
  id: string;
  email: string;
  hash: string;
  role?: string;
  failedAttempts: number;
  lockedUntil: number;
}

interface AttemptRecord {
  count: number;
  resetAt: number;
  blockedUntil: number;
}

const MAX_ATTEMPTS = 5;
const WINDOW_MS = 60_000;
const BLOCK_MS = 5 * 60_000;
const LOCK_MS = 15 * 60_000;

function b64url(buf: Buffer): string {
  return buf.toString("base64").replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

function timingSafeEqual(a: string, b: string): boolean {
  const ba = Buffer.from(a);
  const bb = Buffer.from(b);
  if (ba.length !== bb.length || ba.length === 0) return false;
  return crypto.timingSafeEqual(ba, bb);
}

export class AuthService implements IAuthService {
  private users = new Map<string, UserRecord>();
  private attempts = new Map<string, AttemptRecord>();

  constructor(seedUsers: Array<{ email: string; password: string; role?: string }> = []) {
    for (const u of seedUsers) {
      this.hashPassword(u.password).then((hash) => {
        this.users.set(u.email.toLowerCase(), {
          id: crypto.randomUUID(),
          email: u.email.toLowerCase(),
          hash,
          role: u.role,
          failedAttempts: 0,
          lockedUntil: 0,
        });
      });
    }
  }

  async hashPassword(password: string): Promise<string> {
    const salt = crypto.randomBytes(16);
    const derived = crypto.scryptSync(password, salt, 64, { N: 16384, r: 8, p: 1 });
    return `scrypt$${b64url(salt)}$${b64url(derived)}`;
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    const parts = hash.split("$");
    if (parts.length !== 3 || parts[0] !== "scrypt") return false;
    const salt = Buffer.from(parts[1].replace(/-/g, "+").replace(/_/g, "/"), "base64");
    const expected = Buffer.from(parts[2].replace(/-/g, "+").replace(/_/g, "/"), "base64");
    const derived = crypto.scryptSync(password, salt, expected.length, { N: 16384, r: 8, p: 1 });
    return derived.length === expected.length && crypto.timingSafeEqual(derived, expected);
  }

  async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    const header = b64url(Buffer.from(JSON.stringify({ alg: "HS256", typ: "JWT" })));
    const now = Math.floor(Date.now() / 1000);
    const body = b64url(
      Buffer.from(JSON.stringify({ ...payload, iat: now, exp: now + 3600, jti: crypto.randomUUID() }))
    );
    const sig = b64url(crypto.createHmac("sha256", secret).update(`${header}.${body}`).digest());
    return `${header}.${body}.${sig}`;
  }

  static verifyToken(token: string, secret: string): { valid: boolean; payload?: any } {
    const parts = token.split(".");
    if (parts.length !== 3) return { valid: false };
    const [header, body, sig] = parts;
    const expected = b64url(crypto.createHmac("sha256", secret).update(`${header}.${body}`).digest());
    if (!timingSafeEqual(sig, expected)) return { valid: false };
    try {
      const payload = JSON.parse(Buffer.from(body.replace(/-/g, "+").replace(/_/g, "/"), "base64").toString());
      if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) return { valid: false };
      return { valid: true, payload };
    } catch {
      return { valid: false };
    }
  }

  private checkRateLimit(ip: string): { allowed: boolean; retryAfter?: number } {
    const now = Date.now();
    const rec = this.attempts.get(ip);
    if (!rec) return { allowed: true };
    if (rec.blockedUntil > now) return { allowed: false, retryAfter: Math.ceil((rec.blockedUntil - now) / 1000) };
    if (rec.resetAt <= now) {
      this.attempts.delete(ip);
      return { allowed: true };
    }
    return { allowed: true };
  }

  private recordFailure(ip: string): void {
    const now = Date.now();
    const rec = this.attempts.get(ip) ?? { count: 0, resetAt: now + WINDOW_MS, blockedUntil: 0 };
    if (rec.resetAt <= now) {
      rec.count = 0;
      rec.resetAt = now + WINDOW_MS;
    }
    rec.count++;
    if (rec.count >= MAX_ATTEMPTS) {
      rec.blockedUntil = now + BLOCK_MS;
      rec.count = 0;
      rec.resetAt = now + WINDOW_MS;
    }
    this.attempts.set(ip, rec);
  }

  async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    const ip = request.ip ?? "unknown";
    const rl = this.checkRateLimit(ip);
    if (!rl.allowed) {
      return { status: 429, body: { error: "Too many requests", retryAfter: rl.retryAfter } };
    }

    const email = (request.email ?? "").trim().toLowerCase();
    const password = request.password ?? "";
    if (!email || !password || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      return { status: 400, body: { error: "Valid email and password are required" } };
    }

    const user = this.users.get(email);
    const now = Date.now();
    if (user && user.lockedUntil > now) {
      return { status: 423, body: { error: "Account locked", retryAfter: Math.ceil((user.lockedUntil - now) / 1000) } };
    }

    const ok = user ? await this.verifyPassword(password, user.hash) : false;
    if (!ok || !user) {
      this.recordFailure(ip);
      if (user) {
        user.failedAttempts++;
        if (user.failedAttempts >= MAX_ATTEMPTS) {
          user.failedAttempts = 0;
          user.lockedUntil = now + LOCK_MS;
        }
      }
      return { status: 401, body: { error: "Invalid credentials" } };
    }

    this.attempts.delete(ip);
    user.failedAttempts = 0;
    const token = await this.generateToken({ id: user.id, email: user.email, role: user.role }, user.id);
    return { status: 200, body: { token, user: { id: user.id, email: user.email, role: user.role } } };
  }
}

export default AuthService;

