const DEFAULT_FAILURE_THRESHOLD = 5;
const DEFAULT_RESET_TIMEOUT_MS = 30000;

export class CircuitBreaker {
  private _state: CircuitState = 'CLOSED';
  private failureCount = 0;
  private lastFailureTimestamp = 0;
  private readonly failureThreshold: number;
  private readonly resetTimeoutMs: number;

  constructor(options: CircuitBreakerOptions = {}) {
    this.failureThreshold = options.failureThreshold ?? DEFAULT_FAILURE_THRESHOLD;
    this.resetTimeoutMs = options.resetTimeoutMs ?? DEFAULT_RESET_TIMEOUT_MS;
  }

  get state(): CircuitState { return this._state; }

  getState(): CircuitState { return this._state; }

  recordSuccess(): void {
    this.failureCount = 0;
    if (this._state === 'HALF_OPEN') {
      this._state = 'CLOSED';
    }
  }

  recordFailure(): void {
    this.failureCount += 1;
    this.lastFailureTimestamp = Date.now();
    if (this._state === 'HALF_OPEN') {
      this._state = 'OPEN';
      return;
    }
    if (this._state === 'CLOSED' && this.failureCount >= this.failureThreshold) {
      this._state = 'OPEN';
    }
  }

  private isResetTimeoutElapsed(): boolean {
    return Date.now() - this.lastFailureTimestamp >= this.resetTimeoutMs;
  }

  async execute<T>(action: () => Promise<T>): Promise<T> {
    if (this._state === 'OPEN') {
      if (!this.isResetTimeoutElapsed()) {
        throw new Error('Circuit breaker is open');
      }
      this._state = 'HALF_OPEN';
    }

    try {
      const result = await action();
      this.recordSuccess();
      return result;
    } catch (error) {
      this.recordFailure();
      throw error;
    }
  }
}
